-- Simulated local auth only. Output the real SQL contract for the server receiver regression.
begin;
create temporary table mdq(actor uuid,other uuid,wid uuid,sid uuid,meeting uuid,request uuid,agent uuid,claim uuid,packet jsonb,receipt jsonb);
insert into mdq values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,null);
insert into auth.users(id) select actor from mdq union all select other from mdq;
insert into public.bizoveya_workspaces(id,owner_id,name) select wid,actor,'Delivery fixture' from mdq;
insert into public.bizoveya_memberships(workspace_id,user_id,role) select wid,actor,'owner' from mdq;
insert into public.bizoveya_sites(id,workspace_id,name,mode,kind,status,created_by) select sid,wid,'Packet site','native_business','business','active',actor from mdq;
insert into bizoveya_private.site_agent_rosters(site_id,version,document,actor_id) select sid,1,jsonb_build_object('enabled',true,'agents',jsonb_build_array(jsonb_build_object('kind','content','agentId',agent,'agentVersion',5))),actor from mdq;
create function pg_temp.mdexpect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;end if;raise;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;
grant all on mdq to authenticated,service_role;
select bizoveya_private.set_platform_admin(actor,true,'fixture','Synthetic delivery operator') from mdq;
select bizoveya_private.set_platform_admin(other,true,'fixture','Synthetic unrelated operator') from mdq;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select actor::text from mdq),true);
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select public.bz_agency_command(wid,sid,jsonb_build_object('action','meeting','id',meeting,'agenda','Compare safe private launch options.','mode','deliberation','participants',jsonb_build_array('content'),'reviewed',true,'inputMode','text')) from mdq;
select public.bz_agency_command(wid,sid,jsonb_build_object('action','accept-decision','id',meeting,'expectedVersion',1,'reason','Prepare private approved-context options only.','reviewed',true)) from mdq;
select public.bz_distribute_meeting_request(wid,sid,jsonb_build_object('id',meeting,'requestId',request,'expectedVersion',2,'instruction','Prepare private launch drafts.','channels',jsonb_build_array('blog'),'reviewed',true)) from mdq;
select public.bz_invite_meeting_participants(wid,sid,jsonb_build_object('id',meeting,'expectedVersion',3,'reviewed',true)) from mdq;
do $$declare q jsonb;begin q:=public.bz_admin_meeting_delivery_queue();if jsonb_array_length(q)<>1 or q#>>'{0,blocked}'<>'false' or q#>>'{0,participants,0,state}'<>'invited' then raise exception 'Owner delivery queue mismatch';end if;end;$$;
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
select pg_temp.mdexpect('select public.bz_admin_meeting_delivery_queue()','bz_mfa_required');
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select set_config('request.jwt.claim.sub',(select other::text from mdq),true);
do $$begin if public.bz_admin_meeting_delivery_queue()<>'[]'::jsonb then raise exception 'Unrelated admin saw private packets';end if;end;$$;
select set_config('request.jwt.claim.sub',(select actor::text from mdq),true);
reset role;
update bizoveya_private.site_agent_rosters set document=jsonb_set(document,'{enabled}','false') where site_id=(select sid from mdq);
set local role authenticated;
do $$begin if public.bz_admin_meeting_delivery_queue()#>>'{0,blocked}'<>'true' then raise exception 'Paused team delivery not blocked';end if;end;$$;
reset role;
update bizoveya_private.site_agent_rosters set document=jsonb_set(document,'{enabled}','true') where site_id=(select sid from mdq);
set local role service_role;
select pg_temp.mdexpect('select public.bz_admin_meeting_delivery_queue()','permission denied');
update mdq set packet=public.bz_claim_meeting_invitation(meeting,'content',claim,agent,5);
update mdq set receipt=public.bz_finish_meeting_invitation(meeting,'content',claim,agent,5,'acknowledged','Content receipt worker validated the pinned packet; no reasoning or task execution occurred.');
select public.bz_finish_meeting_invitation(meeting,'content',claim,agent,5,'acknowledged','Content receipt worker validated the pinned packet; no reasoning or task execution occurred.') from mdq;
reset role;
set local role authenticated;
select jsonb_build_object('input',jsonb_build_object('meetingId',meeting,'role','content','agentId',agent,'agentVersion',5,'meetingVersion',4,'sourceVersion',3,'rosterVersion',1,'claimId',claim,'reviewed',true),'packet',packet,'receipt',receipt,'queue',public.bz_admin_meeting_delivery_queue()) as contract059 from mdq;
reset role;
do $$begin
 if (select count(*) from bizoveya_private.meeting_participant_receipts where meeting_id=(select meeting from mdq))<>3 then raise exception 'Terminal retry duplicated receipts';end if;
 if exists(select 1 from bizoveya_private.generation_runs) or exists(select 1 from bizoveya_private.spending_ledger) then raise exception 'Delivery reserved or executed work';end if;
end;$$;
update bizoveya_private.agency_records set version=5 where id=(select meeting from mdq);
set local role authenticated;
do $$begin if public.bz_admin_meeting_delivery_queue()#>>'{0,blocked}'<>'true' then raise exception 'Stale meeting queue not blocked';end if;end;$$;
reset role;
delete from public.bizoveya_memberships where workspace_id=(select wid from mdq);
set local role authenticated;
do $$begin if public.bz_admin_meeting_delivery_queue()<>'[]'::jsonb then raise exception 'Revoked owner saw packets';end if;end;$$;
reset role;
rollback;
